def count_connected(grid, row_start, row_end, col_start, col_end, target):
    """Count connected components of target color in grid region"""
    h = row_end - row_start
    w = col_end - col_start
    visited = set()
    count = 0

    def bfs(r, c):
        q = [(r, c)]
        visited.add((r, c))
        while q:
            cr, cc = q.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < 28 and 0 <= nc < 21 and (nr, nc) not in visited:
                    if grid[nr][nc] == target:
                        visited.add((nr, nc))
                        q.append((nr, nc))

    for r in range(row_start, row_end):
        for c in range(col_start, col_end):
            if grid[r][c] == target and (r, c) not in visited:
                count += 1
                bfs(r, c)
    return count

